INSERT INTO [etg].[contracts_db_operations] ([key_guid], [ref_function_guid], [ref_input_model_guid], [ref_output_model_guid], [ref_package_guid], [pub_query_mssql], [pub_query_postgres], [pub_query_mysql], [pub_bootstrap_element], [pub_notes]) VALUES ('23C7A012-4640-5644-8479-7A76E318B993', '8AB6E149-2871-597A-963E-62C8F2177FA6', NULL, '9857A5AF-379A-50E6-891D-A5920E00034A', 'F1954052-001D-5818-90DC-1953ADA7ABA1', N'SELECT [cuf].[key_guid], [cud].[pub_name] AS [pub_domain], [cus].[pub_name] AS [pub_subdomain], [cuf].[pub_name], [cuf].[pub_version], [cm].[pub_name] AS [pub_module], [cmf].[pub_name] AS [pub_function], [cpe].[pub_name] AS [pub_role], [cmf].[pub_is_async], (SELECT [cmm].[pub_name] FROM [etg].[contracts_modules_models] AS [cmm] WHERE [cmm].[key_guid] = [cmf].[ref_input_model_guid]) AS [pub_input_model], (SELECT [cmm].[pub_name] FROM [etg].[contracts_modules_models] AS [cmm] WHERE [cmm].[key_guid] = [cmf].[ref_output_model_guid]) AS [pub_output_model], JSON_QUERY((SELECT CONCAT(N''['', STRING_AGG(CONCAT(N''"'', STRING_ESCAPE([cmmf].[pub_name], ''json''), N''"''), N'','') WITHIN GROUP (ORDER BY [cmmf].[pub_ordinal]), N'']'') FROM [etg].[contracts_modules_models_fields] AS [cmmf] WHERE [cmmf].[ref_model_guid] = [cmf].[ref_input_model_guid])) AS [pub_fields] FROM [etg].[contracts_urn_functions] AS [cuf] JOIN [etg].[contracts_urn_namespaces] AS [cun] ON [cun].[key_guid] = [cuf].[ref_namespace_guid] JOIN [etg].[contracts_urn_domains] AS [cud] ON [cud].[key_guid] = [cuf].[ref_domain_guid] JOIN [etg].[contracts_urn_subdomains] AS [cus] ON [cus].[key_guid] = [cuf].[ref_subdomain_guid] JOIN [etg].[contracts_modules_functions] AS [cmf] ON [cmf].[key_guid] = [cuf].[ref_module_function_guid] JOIN [etg].[contracts_modules] AS [cm] ON [cm].[key_guid] = [cmf].[ref_module_guid] LEFT JOIN [etg].[contracts_primitives_enums] AS [cpe] ON [cpe].[key_guid] = [cm].[ref_role_enum_guid] WHERE [cun].[pub_name] = ''urn'' ORDER BY [cud].[pub_name], [cus].[pub_name], [cuf].[pub_name], [cuf].[pub_version] FOR JSON PATH, INCLUDE_NULL_VALUES', NULL, NULL, 0, N'One row per function of the urn namespace that is bound to a module function: the RPC registry RpcExecutionModule loads at startup. An unbound function is not listed and so cannot be dispatched. pub_fields: the input model field names in ordinal order.');
